<?php require '_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$label=trim($_POST['label']??'BATTLE READY');$desc=trim($_POST['description']??'');$rules=trim($_POST['rules']??'');$date=$_POST['date']??'';$deadline=$_POST['deadline']??'';$fee=max(0,(float)($_POST['fee']??0));$prize=max(0,(float)($_POST['prize']??0));$max=max(1,(int)($_POST['max']??32));$status=$_POST['status']??'upcoming';$mode=$_POST['mode']??'Squad TPP';if($name===''){flash('danger','Tournament name is required.');go('tournaments.php');}if($id){$s=$pdo->prepare("UPDATE tournaments SET name=?,short_label=?,description=?,rules=?,mode=?,tournament_date=?,registration_deadline=?,entry_fee=?,prize_pool=?,max_teams=?,status=? WHERE tournament_id=?");$s->execute([$name,$label,$desc,$rules,$mode,$date,$deadline,$fee,$prize,$max,$status,$id]);flash('success','Tournament updated.');}else{$s=$pdo->prepare("INSERT INTO tournaments(name,short_label,description,rules,mode,tournament_date,registration_deadline,entry_fee,prize_pool,max_teams,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$name,$label,$desc,$rules,$mode,$date,$deadline,$fee,$prize,$max,$status,(int)$_SESSION['admin_id']]);flash('success','Tournament created.');}go('tournaments.php');}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM tournaments WHERE tournament_id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query("SELECT * FROM tournaments ORDER BY tournament_date DESC")->fetchAll();$pageTitle='Tournament control';require '../includes/header.php';?><section class="page-hero compact"><div class="eyebrow">ADMIN / TOURNAMENT OPERATIONS</div><h1>TOURNAMENT <span>CONTROL.</span></h1><p>Create, edit, and configure tournament fees, prize pools, deadlines, and team limits.</p></section><?php require 'nav.php';?><div class="form-layout section"><section class="box"><div class="eyebrow"><?=$edit?'EDIT TOURNAMENT':'CREATE TOURNAMENT'?></div><h2><?=$edit?'Update lobby':'New lobby'?></h2><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=(int)($edit['tournament_id']??0)?>"><label>Tournament name<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Banner label<input name="label" value="<?=e($edit['short_label']??'BATTLE READY')?>"></label><div class="row g-3"><div class="col-md-6"><label>Entry fee (₹)<input type="number" min="0" step=".01" name="fee" value="<?=e($edit['entry_fee']??'100')?>"></label></div><div class="col-md-6"><label>Prize pool (₹)<input type="number" min="0" step=".01" name="prize" value="<?=e($edit['prize_pool']??'5000')?>"></label></div><div class="col-md-6"><label>Max teams<input type="number" min="1" name="max" value="<?=e($edit['max_teams']??32)?>"></label></div><div class="col-md-6"><label>Mode<select name="mode"><?php foreach(['Squad TPP','Squad FPP','Solo TPP','Duo TPP'] as $m):?><option <?=($edit['mode']??'Squad TPP')===$m?'selected':''?>><?=e($m)?></option><?php endforeach;?></select></label></div><div class="col-md-6"><label>Tournament date/time<input type="datetime-local" name="date" required value="<?=e(isset($edit['tournament_date'])?date('Y-m-d\TH:i',strtotime($edit['tournament_date'])):'')?>"></label></div><div class="col-md-6"><label>Registration deadline<input type="datetime-local" name="deadline" required value="<?=e(isset($edit['registration_deadline'])?date('Y-m-d\TH:i',strtotime($edit['registration_deadline'])):'')?>"></label></div><div class="col-12"><label>Status<select name="status"><?php foreach(['upcoming','open','live','completed','cancelled'] as $s):?><option value="<?=$s?>" <?=($edit['status']??'open')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></label></div></div><label>Description<textarea name="description" required rows="3"><?=e($edit['description']??'')?></textarea></label><label>Rules<textarea name="rules" rows="3"><?=e($edit['rules']??'')?></textarea></label><button class="btn btn-hot"><?=$edit?'Save changes':'Create tournament'?> ↗</button><?php if($edit):?><a href="tournaments.php" class="btn btn-quiet">Cancel edit</a><?php endif;?></form></section><section class="box"><div class="eyebrow">EXISTING LOBBIES</div><h2>Published tournaments</h2><?php foreach($rows as $t):?><div class="list-row"><div><b><?=e($t['name'])?></b><small><?=e(date('d M Y',strtotime($t['tournament_date'])))?> · ₹<?=number_format($t['entry_fee'])?> · <?=e($t['status'])?></small></div><a class="text-link" href="?edit=<?=(int)$t['tournament_id']?>">Edit ↗</a></div><?php endforeach;?></section></div><?php require '../includes/footer.php';?>
